1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Membership tier for pet owners. An owner is {@code SILVER} when its {@code namesakeCount} is 0
5	 * (no existing owner shares its first and last name) and it has an email address; otherwise it is
6	 * {@code BRONZE}. Derived purely from the owner's own state, so it carries no stored data and is
7	 * seed-independent. Used by the owner mapper to expose {@code membershipTier} on responses.
8	 */
9	public final class MembershipTier {
10	
11	    private MembershipTier() {
12	    }
13	
14	    /**
15	     * The membership tier for the given namesake count and email: {@code SILVER} when the count is
16	     * exactly 0 and the email is present (non-null, non-blank), otherwise {@code BRONZE}.
17	     */
18	    public static String of(Integer namesakeCount, String email) {
19	        boolean unique = namesakeCount != null && namesakeCount == 0;
20	        boolean hasEmail = email != null && !email.isBlank();
21	        return unique && hasEmail ? "SILVER" : "BRONZE";
22	    }
23	}
