1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	
9	/**
10	 * Step of {@code POST /api/owners} that rejects a create when another owner already has the same
11	 * last name and address, throwing {@link DuplicateHouseholdException} (handled as 409 Conflict).
12	 * Last name and address are compared case-insensitively with collapsed whitespace. The check is
13	 * skipped when the request opts in with {@code sharesHousehold=true}. Runs after
14	 * {@link RequireOwnerFields} has published the validated body and before {@link BuildOwner}/
15	 * {@link SaveOwner} persist the new owner.
16	 */
17	public class RequireUniqueHousehold {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateHouseholdException {
21	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
22	            return; // owner explicitly shares a household with an existing owner
23	        }
24	        String lastName = Household.normalize(request.getLastName());
25	        String address = Household.normalize(request.getAddress());
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (lastName.equals(Household.normalize(existing.getLastName()))
28	                    && address.equals(Household.normalize(existing.getAddress()))) {
29	                throw new DuplicateHouseholdException(
30	                        "An owner with the same last name and address already exists");
31	            }
32	        }
33	    }
34	}
