8	
9	public class BuildOwner {
10	
11	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
12	        Owner owner = ownerMapper.toOwner(request);
13	        // The effective registration date (supplied or defaulted to today) must fall on a business
14	        // day: a weekend rolls forward to the next Monday. Everything derived from the registration
15	        // date (membership number, daily limit) then uses this adjusted date.
16	        owner.setRegistrationDate(BusinessDay.effectiveRegistrationDate(owner.getRegistrationDate()));
17	        built.set(owner);
18	    }
19	}
