1	package org.springframework.samples.petclinic.acceptance;
2	
3	import org.junit.jupiter.api.Test;
4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
5	import tools.jackson.databind.node.ObjectNode;
6	
7	/** tier-gold: membershipTier is 'GOLD' when the owner's household has 3+ members after this
8	 * create. Build a shared household (same lastName + address, sharesHousehold) and assert the third
9	 * member is GOLD. */
10	class AcceptanceTest extends AcceptanceBase {
11	
12		@Test
13		void coreGoldForThreeMemberHousehold() throws Exception {
14			String lastName = uniqueLastName();
15			String address = uniqueAddress();
16			for (int i = 0; i < 2; i++) {
17				ObjectNode m = ownerNode();
18				m.put("lastName", lastName);
19				m.put("address", address);
20				m.put("sharesHousehold", true);
21				createOwnerOk(m);
22			}
23			ObjectNode third = ownerNode();
24			third.put("lastName", lastName);
25			third.put("address", address);
26			third.put("sharesHousehold", true);
27			int id = createOwnerOk(third);
28			getOwner(id).andExpect(jsonPath("$.membershipTier").value("GOLD"));
29		}
30	}
